async function seedBadgeConfigs() {
  try {
    await connectToDatabase2();
    const existingCount = await badge_config_model_default.countDocuments();
    if (existingCount === 0) {
      const savedDefaults = getDefaultBadges();
      if (savedDefaults && savedDefaults.length > 0) {
        console.log(`\u{1F331} Seeding badge configs from saved white-label defaults (${savedDefaults.length} badges)...`);
        await badge_config_model_default.insertMany(savedDefaults);
        console.log(`\u2705 Seeded ${savedDefaults.length} badges from saved defaults`);
      } else {
        console.log("\u{1F331} Seeding default badge configurations from constants...");
        await badge_config_model_default.insertMany(
          BADGES.map((badge) => ({
            id: badge.id,
            name: badge.name,
            description: badge.description,
            category: badge.category,
            icon: badge.icon,
            rarity: badge.rarity,
            condition: badge.condition,
            minLevel: badge.minLevel || 0,
            isActive: true
          }))
        );
        console.log(`\u2705 Seeded ${BADGES.length} default badges from constants`);
      }
    } else {
      const existingBadges = await badge_config_model_default.find({}).lean();
      const existingIds = new Set(existingBadges.map((b) => b.id));
      let added = 0;
      let updated = 0;
      for (const badge of BADGES) {
        if (!existingIds.has(badge.id)) {
          await badge_config_model_default.create({
            id: badge.id,
            name: badge.name,
            description: badge.description,
            category: badge.category,
            icon: badge.icon,
            rarity: badge.rarity,
            condition: badge.condition,
            minLevel: badge.minLevel || 0,
            isActive: true
          });
          added++;
        } else {
          const existing = existingBadges.find((b) => b.id === badge.id);
          const conditionChanged = JSON.stringify(existing?.condition) !== JSON.stringify(badge.condition);
          if (conditionChanged) {
            await badge_config_model_default.updateOne(
              { id: badge.id },
              {
                $set: {
                  condition: badge.condition,
                  name: badge.name,
                  description: badge.description,
                  category: badge.category,
                  icon: badge.icon,
                  rarity: badge.rarity,
                  minLevel: badge.minLevel || 0
                }
              }
            );
            updated++;
          }
        }
      }
      if (added > 0 || updated > 0) {
        console.log(`\u{1F504} Badge sync: ${added} added, ${updated} updated (${existingCount} existed)`);
      } else {
        console.log(`\u2139\uFE0F Badges already synced (${existingCount} badges found)`);
      }
    }
  } catch (error47) {
    console.error("\u274C Error seeding badge configs:", error47);
    throw error47;
  }
}
async function getBadgesFromDB() {
  try {
    await connectToDatabase2();
    let badges = await badge_config_model_default.find({ isActive: true }).lean();
    if (badges.length === 0) {
      await seedBadgeConfigs();
      badges = await badge_config_model_default.find({ isActive: true }).lean();
    }
    return badges.map((badge) => ({
      id: badge.id,
      name: badge.name,
      description: badge.description,
      category: badge.category,
      icon: badge.icon,
      rarity: badge.rarity,
      condition: badge.condition,
      minLevel: badge.minLevel || 0,
      isActive: badge.isActive
    }));
  } catch (error47) {
    console.error("Error fetching badges from DB, using constants:", error47);
    return BADGES;
  }
}
